const textParts=value=>{const match=String(value).match(/^(\s*)([\s\S]*?)(\s*)$/);return {before:match?.[1]||'',text:match?.[2]||'',after:match?.[3]||''}};
const translatableNode=node=>{
  if(!node?.parentElement)return false;
  if(!node.nodeValue.trim())return false;
  return !node.parentElement.closest('script,style,noscript,code,pre,option,[data-i18n],[data-i18n-placeholder],[data-no-translate]');
};
function collectTranslatables(){
  const entries=[];
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:node=>translatableNode(node)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT});
  let node;
  while(node=walker.nextNode()){
    if(!originalText.has(node))originalText.set(node,textParts(node.nodeValue));
    const source=originalText.get(node);
    if(source.text)entries.push({kind:'text',node,source});
  }
  document.querySelectorAll('[placeholder],[aria-label],[title],[alt]').forEach(element=>{
    if(element.closest('.language-select,[data-no-translate]'))return;
    ['placeholder','aria-label','title','alt'].forEach(attribute=>{
      if(!element.hasAttribute(attribute))return;
      let saved=originalAttributes.get(element);
      if(!saved){saved={};originalAttributes.set(element,saved)}
      if(!saved[attribute])saved[attribute]=element.getAttribute(attribute);
      if(saved[attribute])entries.push({kind:'attribute',element,attribute,source:{before:'',text:saved[attribute],after:''}});
    });
  });
  return entries;
}
