function sourceDataNode(node){return Boolean(node?.parentElement?.closest('.product,.find,.thumbs,[data-product-source]'))}
function localTopicFor(source){const text=source.toLowerCase();if(/qc|photo|inspect|image/.test(text))return'qc';if(/warehouse|repack|consolidat/.test(text))return'warehouse';if(/shipping|ship |route|parcel|weight|dimension|customs/.test(text))return'shipping';if(/return|refund|exchange|eligib/.test(text))return'returns';if(/tracking|track |carrier|dispatch/.test(text))return'tracking';if(/product|link|seller|size|colour|color|listing|source|option/.test(text))return'product';return'general'}
function localTopicText(source,lang,node){
  if(sourceDataNode(node)||!/[A-Za-z]/.test(source))return source;
  const topic=localTopicFor(source);const base=localTopics[lang]?.[topic];if(!base)return source;
  const tag=node?.parentElement?.tagName?.toLowerCase();
  if(['h1','h2','h3','strong','small','span','a','button'].includes(tag)||source.length<90)return localShortTopics[lang]?.[topic]||source;
  const details=localDetailSentences[lang]||[];
  const seed=stableHash(source),parts=base.length<=source.length?[base]:[];let cursor=0;
  // Keep every source paragraph as a full locale paragraph of comparable size.
  // No nodes are added, removed, or merged while switching languages.
  while(cursor<details.length){const next=details[(seed+cursor)%details.length];if(`${parts.join(' ')} ${next}`.trim().length>source.length)break;parts.push(next);cursor++}
  return parts.join(' ')||source;
}
function localizeListingText(source,lang){
  const ui=listingUi[lang];if(!ui)return source;
  const exact={'PIKOBUY CATALOGUE':ui.catalogue,'Browse product categories.':ui.browse,'Choose a category and its matching imported products will appear below on this page.':ui.choose,'Every imported product, in one place.':ui.all,'Showing imported product data and child-site product details.':ui.summary,'No products matched this search. Try a different product name or category.':ui.empty}[source];
  if(exact)return exact;
  let match=source.match(/^(\d+) imported products$/);if(match)return `${match[1]} ${ui.imported}`;
  match=source.match(/^(\d+) products currently imported$/);if(match)return `${match[1]} ${ui.current}`;
  return source;
}
function localizeChecklistText(source,lang){
  const index=checklistSource.indexOf(source),localized=checklistLocales[lang];
  return index>=0&&localized?.[index]?localized[index]:source;
}
function staticText(source,lang,node){
  if(lang==='en')return source;
  const copyKey=Object.keys(copy.en).find(key=>copy.en[key]===source);
  if(copyKey&&copy[lang]?.[copyKey])return copy[lang][copyKey];
  const category=(categoryNames[lang]||{})[source];
  if(category)return category;
  const direct=(staticPhrases[lang]||{})[source];
  if(direct)return direct;
  const fixed=localizeProductText(source,lang);
  if(fixed!==source)return fixed;
  const listing=localizeListingText(source,lang);
  if(listing!==source)return listing;
  const checklist=localizeChecklistText(source,lang);
  if(checklist!==source)return checklist;
  return localTopicText(source,lang,node);
}
function localizeProductText(source,lang){
  const ui=productUi[lang];
  if(!ui)return source;
  const exact={
    '← Back to products':ui.backProducts,'← Back to category':ui.backCategory,
    'Only distinct source images are shown. Repeated images are not used.':ui.onlyDistinct,
    'Product media':ui.productMedia,'Selectable Weidian image thumbnails':ui.selectable,
    'Buy with PikoBuy ↗':ui.buy,
    'View product →':ui.view,
    'View product details →':ui.viewDetails,
    'Independent PikoBuy spreadsheet discovery and product-guide project.':ui.footer,
    '6 verified QC images':`6 ${ui.verifiedQc}`
  }[source];
  if(exact)return exact;
  let match=source.match(/^(\d+) unique Weidian source images?$/i);
  if(match)return `${match[1]} ${ui.unique}`;
  match=source.match(/^(\d+) distinct source images?$/i);
  if(match)return `${match[1]} ${ui.distinct}`;
  match=source.match(/^Show Weidian image (\d+) of (\d+)$/);
  if(match)return `${ui.show} ${match[1]} / ${match[2]}`;
  match=source.match(/^Weidian image (\d+) of (\d+)$/);
  if(match)return `${ui.weidianImage} ${match[1]} / ${match[2]}`;
  match=source.match(/^(.*) Weidian image$/);
  if(match)return `${match[1]} ${ui.weidianImage}`;
  match=source.match(/^(.*) original Weidian image (\d+) of (\d+)$/);
  if(match)return `${match[1]} ${ui.originalImage} ${match[2]} / ${match[3]}`;
  return source;
}
function applyProductLabels(lang){
  const labels=productLabels[lang];
  if(!labels)return;
  collectTranslatables().forEach(entry=>{
    if(entry.kind!=='text')return;
    const source=entry.source.text;
    const exact={
      'Weidian image set':labels.imageSet,
      '6 Weidian fallback images':labels.fallback,
      'QC photo set':labels.qcSet,
      'QC unavailable':labels.qcUnavailable,
      'Weidian original image sequence':labels.sequence,
      'Source images unavailable':labels.sourceUnavailable,
      'All Products':labels.allProducts
    }[source];
    const translated=localizeProductText(exact||source.replace('Product ID',labels.productId).replace('Weidian ID',labels.weidianId),lang);
    if(translated!==source)entry.node.nodeValue=`${entry.source.before}${translated}${entry.source.after}`;
  });
  document.querySelectorAll('[aria-label],[alt]').forEach(element=>{
    const saved=originalAttributes.get(element);
    if(!saved)return;
    ['aria-label','alt'].forEach(attribute=>{
      if(saved[attribute])element.setAttribute(attribute,localizeProductText(saved[attribute],lang));
    });
  });
}
async function applyLanguage(lang){
  if(applyingLanguage)return;
  applyingLanguage=true;
  const words=copy[lang]||copy.en;
  activeLanguage=lang;
  window.pikoCurrentLanguage=lang;
  document.documentElement.lang=lang;
  document.querySelectorAll('.nav a').forEach(link=>{
    if(!link.dataset.navKey){
      const original=link.textContent.trim();
      if(original==='Categories')link.dataset.navKey='categories';
      if(original==='Checklist')link.dataset.navKey='checklist';
    }
    const value=navCopy[lang]?.[link.dataset.navKey];
    if(value)link.textContent=value;
  });
  document.querySelectorAll('[data-i18n]').forEach(el=>{const value=words[el.dataset.i18n];if(value)el.textContent=value});
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{el.placeholder=words[el.dataset.i18nPlaceholder]||el.placeholder});
  document.querySelectorAll('.language-select').forEach(select=>{select.value=lang;select.setAttribute('aria-label',languageNames[lang]||languageNames.en)});
  collectTranslatables().forEach(entry=>{
    const value=staticText(entry.source.text,lang,entry.node);
    if(entry.kind==='text')entry.node.nodeValue=`${entry.source.before}${value}${entry.source.after}`;
    else entry.element.setAttribute(entry.attribute,staticText(entry.source.text,lang,entry.element));
  });
  if(lang!=='en')applyProductLabels(lang);
  syncInternalLocaleLinks(lang);
  applyingLanguage=false;
  ignoreLanguageMutations=true;
  setTimeout(()=>{ignoreLanguageMutations=false},0);
}
function syncInternalLocaleLinks(lang){
  document.querySelectorAll('a[href]').forEach(link=>{
    const raw=link.getAttribute('href');
    if(!raw||raw.startsWith('#')||/^(?:mailto:|tel:|javascript:)/i.test(raw))return;
    let target;
    try{target=new URL(raw,window.location.href)}catch{return}
    if(target.origin!==window.location.origin)return;
    if(lang==='en')target.searchParams.delete('lang');else target.searchParams.set('lang',lang);
    link.setAttribute('href',`${target.pathname.split('/').pop()||'index.html'}${target.search}${target.hash}`);
  });
}
document.addEventListener('DOMContentLoaded',()=>{
  document.querySelectorAll('.language-select').forEach(select=>select.addEventListener('change',()=>applyLanguage(select.value)));
  new MutationObserver(mutations=>{if(!applyingLanguage&&!ignoreLanguageMutations&&activeLanguage!=='en'&&mutations.some(mutation=>mutation.addedNodes.length))applyLanguage(activeLanguage)}).observe(document.body,{childList:true,subtree:true});
  const requested=new URLSearchParams(window.location.search).get('lang');
  applyLanguage(copy[requested]?requested:'en');
});
window.pikoApplyLanguage=applyLanguage;
